import java.util.*;
import java.io.*;

public class Main {
    static final long INF = (long)1e15;
    static final int MAX_VAL = 1000010;
    static List<Long> sequence = new ArrayList<>();
    static int minSteps = MAX_VAL;

    static void recurse(long x, int steps) {
        if (steps > minSteps)
            return;
        if (x == 0) {
            minSteps = steps;
            return;
        }
        int lowerIdx = Collections.binarySearch(sequence, x);
        if (lowerIdx < 0) {
            lowerIdx = -lowerIdx - 1;
        }
        int upperIdx = lowerIdx;
        if (upperIdx >= sequence.size()) {
            upperIdx = sequence.size() - 1;
        }
        long lowerVal = sequence.get(lowerIdx);
        long upperVal = sequence.get(upperIdx);
        if (lowerIdx == upperIdx && lowerIdx > 0) {
            lowerIdx--;
            lowerVal = sequence.get(lowerIdx);
        }
        long diff1 = x - lowerVal;
        int cost = lowerIdx;
        long diff2 = upperVal - x;
        recurse(x % lowerVal, steps + cost * (x / lowerVal));
        recurse(diff2, steps + cost + 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        sequence.add(0L);
        for (int i = 1; i <= 16; ++i) {
            sequence.add(sequence.get(sequence.size() - 1) * 10 + 1);
        }
        recurse(n, 0);
        System.out.println(minSteps);
    }
}
